import {expeditionHudMarkup} from './hud-markup.js';
import {glyph} from './ui-art.js';
import {orbSlotMarkup} from './approved-orb-presentation.js';
import {HUD_WIDGETS} from './hud-layout.js';
import {createHudLayoutPresenter} from './hud-layout-presenter.js';
import {updateBossPresentation} from './boss-hud.js';
import {layoutMinibossHud} from './cave-miniboss-hud.js';
import {BOSSES} from './bosses.js';

const files=['screen.css','readable.css','expedition.css','expedition-hud.css','expedition-hud-host.css','approved-expedition-hud.css','cave-descent-hud.css','approved-cave-alerts-ui.css','run-orb-hud.css','cave-miniboss-hud.css','boss-hud.css','hud-layout.css'];
const scoped=css=>css.replace(/(^|[},\s])body((?:\.[\w-]+)*)/gm,(_,prefix,classes)=>prefix+(classes?':host('+classes+')':':host')).replace(/:root\b/g,':host');
export async function createHudEditorPreview(container,{document:doc,background,width,height,uiScale=1,onSelect,onDrag}={}){
 const host=doc.createElement('div');host.className='hud-v5 hud-v3 hud-clean-v5 immersive-run';host.style.cssText='position:absolute;transform-origin:0 0;';container.append(host);const shadow=host.attachShadow({mode:'open'});
 const css=await Promise.all(files.map(async name=>{const response=await fetch(new URL(name,import.meta.url));if(!response.ok)throw Error('preview-style');return response.text();}));
 shadow.innerHTML='<style>@layer ui-layout-r2;'+css.map(scoped).join('\n')+`\n:host{display:block;color-scheme:dark}#stage{position:relative!important;width:${width}px!important;height:${height}px!important;overflow:hidden!important;background:#06132b;background-size:100% 100%;border:0!important}.plane{position:absolute;inset:0;zoom:${uiScale};pointer-events:none}#hud5Root{position:absolute;inset:0;--combo-color:#35d6f2}.hits{position:absolute;inset:0;pointer-events:none;z-index:9999}.edit-hit{position:absolute;pointer-events:auto;border:calc(1.5px / var(--fit,1)) dashed #35d6f280;box-sizing:border-box;cursor:grab;touch-action:none;background:transparent;padding:0!important;min-height:0!important;box-shadow:none!important;border-radius:5px;color:white}.edit-hit.selected{border-color:#ffbc00;background:#ffbc000c}.edit-hit:focus-visible{outline:3px solid #edf4ff}.edit-hit span{position:absolute;left:0;top:0;background:#06132be8;border-radius:3px;padding:2px 4px;font:600 calc(11px / var(--fit,1)) GVExpBody,Nunito,sans-serif;white-space:nowrap;pointer-events:none}.edit-hit.hidden-widget{border-style:dotted;background:#06132b44}.resize-grip{position:absolute;right:calc(-3px / var(--fit,1));bottom:calc(-3px / var(--fit,1));width:calc(12px / var(--fit,1));height:calc(12px / var(--fit,1));background:#ffbc00;border:2px solid #020816;border-radius:3px;cursor:nwse-resize;pointer-events:auto}.hits.no-guides .edit-hit:not(.selected){border-color:transparent}.hits.no-guides .edit-hit:not(.selected)>span,.hits.no-guides .hidden-widget{visibility:hidden}.preview-grid{position:absolute;inset:0;pointer-events:none;background-image:linear-gradient(#35d6f21a 1px,transparent 1px),linear-gradient(90deg,#35d6f21a 1px,transparent 1px);background-size:32px 32px}.hud5-star svg{width:100%;height:100%}#boostHud .boost-node{background:none!important}#boostHud{margin-top:auto!important}.preview-demo-note{font:600 12px GVExpBody;color:#bfd0e8} </style><div id="stage"><div class="plane"><div id="hud5Root"></div></div><div class="preview-grid"></div><div class="hits"></div></div>`;
 const stage=shadow.querySelector('#stage'),root=shadow.querySelector('#hud5Root'),hits=shadow.querySelector('.hits'),presenter=createHudLayoutPresenter();if(background)stage.style.backgroundImage='url("'+background+'")';
 let fit=1,selected='life',layout={},scene='cave',guides=true;
 function populate(){presenter.clear();root.innerHTML=expeditionHudMarkup();const set=(id,text)=>{const n=root.querySelector('[data-hud-field="'+id+'"]');if(n)n.textContent=text;};
  const actual=null;for(const [id,value]of Object.entries({hpLabel:'105 / 105',breathLabel:'89 / 100',combo:'147×',runPlace:scene==='abyss'?'Abismo':'Andar 5',runDepth:'125 m',scoreValue:'3.969',runBag:'137 ● · 21 ◇',missionTask:'Quebre cristais',missionProgress:'8 / 12',missionTime:'2:40',trackName:'PRISMA PULSE',bpmLabel:'116 BPM',railMultiplier:'×1.35'}))set(id,actual&&!actual.hidden?actual.querySelector('[data-hud-field="'+id+'"]')?.textContent||value:value);
  for(const name of ['hpBar','breathBar'])root.querySelector('[data-hud-field='+name+']').style.width=name==='hpBar'?'100%':'89%';
  root.querySelector('[data-hud-field=scoreFill]').style.height='43%';root.querySelector('[data-hud-field=scoreMarks]').innerHTML=[1600,3200,5400,7600,9300].map((n,i)=>'<i style="bottom:'+([.176,.353,.588,.824,1][i]*100)+'%">'+n.toLocaleString('pt-BR')+'</i>').join('');
  root.querySelector('[data-hud-field=earnedStars]').innerHTML=[.176,.353,.588,.824,1].map((v,i)=>'<span class="hud5-star-anchor" style="bottom:'+v*100+'%"><i class="star-slot hud5-star '+(i<2?'lit':'')+'">'+glyph('star')+'</i></span>').join('');
  root.querySelector('[data-hud-field=missionIcon]').innerHTML=glyph('gem');root.querySelector('[data-hud-field=missionIcon] svg').style.cssText='width:29px;height:36px';
  root.querySelectorAll('.quantity').forEach((el,i)=>el.textContent=[3,2,1][i]);root.querySelectorAll('.hud-note').forEach((el,i)=>el.style.left=(10+i*22)+'%');root.querySelector('.perfect-zone').style.cssText='left:10%;width:10%';
  const orb=['red','yellow','blue'].map((color,i)=>orbSlotMarkup({color,empty:false,orb:{id:['impact','shelter','stride'][i],name:'Orb',effect:'Exemplo'}})).join('');
  root.querySelector('.hud').insertAdjacentHTML('beforeend',`<div class="hud5-left"><div class="hud5-details"></div><div class="hud5-buffs"><section class="run-orb-tray"><div class="run-orb-slots">${orb}</div></section><div id="boostHud"><div class="boost-node"><b>♨</b><small>Pipoca mineral · 12s</small></div></div></div><div class="hud5-critical"><section id="objective" data-approved-alerts data-alerts-active="false"><small>${scene==='boss'?'Derrote o chefe':'Minere cristais'}</small><div><span>Carga</span><strong>8 / 18</strong></div><div class="meter"><i style="width:44%"></i></div></section></div></div><section class="hud5-cards"><div id="runCards"><div class="card-chip"><span style="width:20px;height:20px">${glyph('force')}</span><span class="hud-card-name">Força mineral</span><small class="hud-card-level">2</small></div></div></section>`);
  root.insertAdjacentHTML('beforeend','<section id="bossHud" class="boss-hud" '+(scene==='boss'?'':'hidden')+'><div><small id="bossPhase">FASE 1</small><strong id="bossName">'+BOSSES[0].name+'</strong><b id="bossHP">140 / 140</b><div class="boss-health"><i id="bossFill" style="width:100%"></i></div></div><div class="boss-command"><strong></strong><span></span></div></section><div class="cave-miniboss-hud"><section class="gv-sentinel cave-miniboss-status" '+(scene==='cave'?'':'hidden')+'><div class="gv-sentinel-head"><strong>Sentinela do Veio</strong><span>Opcional</span></div><div class="cave-miniboss-life"><i style="width:75%"></i></div><div class="gv-sentinel-details"><span>Em combate</span><b>75 / 100</b></div></section></div>');
  root.classList.add('run-orbs-visible');root.querySelectorAll('button').forEach(b=>b.tabIndex=-1);hits.innerHTML='';for(const def of HUD_WIDGETS){const b=doc.createElement('button');b.className='edit-hit';b.dataset.widget=def.id;b.setAttribute('aria-label','Mover '+def.name);b.innerHTML='<span>'+def.name+'</span><i class="resize-grip" hidden></i>';b.addEventListener('pointerdown',e=>onDrag?.(e,def.id,e.target.classList.contains('resize-grip')));b.addEventListener('keydown',e=>onDrag?.(e,def.id,false));b.addEventListener('click',()=>onSelect?.(def.id));hits.append(b);}
 }
 function render(){
  layoutMinibossHud(root);updateBossPresentation(root,{room:{enemies:[{boss:true,bossIndex:0,hp:140,maxHp:140}]}});presenter.frame(root,layout);
  const sr=stage.getBoundingClientRect(),zoom=sr.width/width;host.style.setProperty('--fit',String(fit));
  for(const def of HUD_WIDGETS){const el=[...root.querySelectorAll(def.selector)].find(n=>n.getBoundingClientRect().width>0),box=hits.querySelector('[data-widget='+def.id+']');if(!el){box.hidden=true;continue;}const r=el.getBoundingClientRect();box.hidden=false;Object.assign(box.style,{left:(r.left-sr.left)/zoom+'px',top:(r.top-sr.top)/zoom+'px',width:r.width/zoom+'px',height:r.height/zoom+'px'});box.classList.toggle('selected',selected===def.id);box.classList.toggle('hidden-widget',layout[def.id]?.hidden===true);box.querySelector('.resize-grip').hidden=selected!==def.id;}
  hits.classList.toggle('no-guides',!guides);
 }
 function resize(){fit=Math.max(.05,Math.min(container.clientWidth/width,container.clientHeight/height));host.style.width=width+'px';host.style.height=height+'px';host.style.transform='scale('+fit+')';host.style.left=(container.clientWidth-width*fit)/2+'px';host.style.top=(container.clientHeight-height*fit)/2+'px';render();}
 populate();const observer=new ResizeObserver(resize);observer.observe(container);await doc.fonts.ready;resize();
 return {root,shadow,width,height,setLayout(value){layout=value;render();},select(id){selected=id;const needed=id==='boss'?'boss':id==='sentinel'?'cave':scene;if(needed!==scene){scene=needed;populate();}render();},setScene(value){scene=value;populate();render();},setGuides(value){guides=value;render();},setGrid(value){shadow.querySelector('.preview-grid').hidden=!value;},rect(id){const n=[...root.querySelectorAll(HUD_WIDGETS.find(w=>w.id===id).selector)].find(n=>n.getBoundingClientRect().width>0);if(!n)return null;const r=n.getBoundingClientRect(),rr=root.getBoundingClientRect();return {x:(r.left-rr.left+r.width/2)/rr.width,y:(r.top-rr.top+r.height/2)/rr.height,width:r.width,height:r.height,root:rr};},dispose(){observer.disconnect();presenter.dispose();host.remove();}};
}
